// MIT. Local operator inspection and setup; this command does not authorize a buyer payment.
import { constants } from 'node:fs';
import { readFile, open, mkdir, rm, link, lstat } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { resolve, join, dirname, basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import { openS3ObjectFile } from './source.mjs';
import { compileHttpSellerOffer } from '../seller.mjs';

const HELP = `Usage:
  node cli.mjs describe --source PRIVATE_SOURCE.json
  node cli.mjs inspect --source PRIVATE_SOURCE.json --object ID --out NEW_FILE [--offset N --length N]
  node cli.mjs configure --source PRIVATE_SOURCE.json --payment PAYMENT.json --origin HTTPS_ORIGIN --directory NEW_DIR
  node cli.mjs workspace --state PRIVATE_DIRECTORY [--source SOURCE.json --payment PAYMENT.json --origin HTTPS_ORIGIN]

describe performs authorized private HEAD reads and prints public object contracts.
inspect retrieves one approved object/chunk directly as its local operator, without x402.
configure creates an original SF30 service.json and handlers.mjs for these exact objects.
Credentials stay with the source's configured AWS SDK credential provider.`;

function argsOf(args) {
  if (!args.length || args[0] === '--help') return null;
  const command = args[0], options = new Map();
  const allow = { describe: ['--source'], inspect: ['--source', '--object', '--out', '--offset', '--length'],
    configure: ['--source', '--payment', '--origin', '--directory'] }[command];
  if (!allow) throw new TypeError(HELP);
  for (let i = 1; i < args.length; i += 2) {
    const key = args[i], value = args[i + 1];
    if (!allow.includes(key) || options.has(key) || !value || value.startsWith('--')) throw new TypeError(HELP);
    options.set(key, value);
  }
  const required = { describe: ['--source'], inspect: ['--source', '--object', '--out'],
    configure: ['--source', '--payment', '--origin', '--directory'] }[command];
  if (required.some(key => !options.has(key))) throw new TypeError(HELP);
  return { command, options };
}

async function writeNew(path, data, resume) {
  const expected = Buffer.from(data), temporary = join(dirname(path), '.s3-write-' + randomUUID());
  const file = await open(temporary, 'wx', 0o600);
  try {
    await file.writeFile(expected); await file.sync();
    try { await link(temporary, path); }
    catch (error) {
      if (!resume || error.code !== 'EEXIST') throw error;
      const existing = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
      try {
        const before = await existing.stat({ bigint: true });
        const actual = Buffer.alloc(expected.length + 1); let used = 0;
        if (before.isFile() && before.size === BigInt(expected.length)) {
          while (used < actual.length) {
            const part = await existing.read(actual, used, actual.length - used, null);
            if (!part.bytesRead) break; used += part.bytesRead;
          }
        }
        const after = await existing.stat({ bigint: true });
        if (!before.isFile() || used !== expected.length || before.size !== after.size ||
            before.mtimeNs !== after.mtimeNs || !actual.subarray(0, used).equals(expected)) {
          const conflict = new Error('Existing S3 package file differs from this saved preparation: ' + basename(path));
          conflict.code = 'S3_PACKAGE_CONTENT_CONFLICT'; conflict.status = 409; throw conflict;
        }
      } finally { await existing.close(); }
    }
    const parent = await open(dirname(path), 'r');
    try { await parent.sync(); } finally { await parent.close(); }
  } finally { await file.close(); await rm(temporary, { force: true }); }
}

/** Compile the same original S3 service from an operator-selected description. */
export function compileS3Seller({ payment, origin, description }) {
  const target = new URL(origin);
  if (target.protocol !== 'https:' || target.username || target.password || target.search || target.hash || target.pathname !== '/')
    throw new TypeError('Choose one public HTTPS origin');
  const originText = target.origin;
  const perObject = payment?.schema === 'stellar-forge.s3-payments.v1' ? payment.objects : null;
  if (perObject && (typeof perObject !== 'object' || Array.isArray(perObject) ||
      Object.keys(perObject).some(id => !description.objects.some(item => item.id === id))))
    throw new TypeError('Payment map must match configured object IDs');
  const routes = description.objects.map((item, i) => {
    const terms = perObject ? perObject[item.id] : payment;
    const definition = { method: 'GET', description: `${item.description} Object snapshot: ${item.snapshot}.`,
      serviceName: 'Private object downloads', tags: ['data', 'download'], payment: terms,
      ...(item.mode === 'chunks' ? { queryParameters: [
        { name: 'offset', type: 'integer', description: 'Zero-based byte offset', example: 0 },
        { name: 'length', type: 'integer', description: `At most ${item.maxBytes} bytes; final chunk may be shorter`, example: item.maxBytes },
      ] } : {}) };
    const offer = compileHttpSellerOffer({ ...definition, url: originText + item.path });
    offer.resource.mimeType = item.contentType;
    // The original compiler's optional output example describes JSON. An opaque
    // file has no JSON output declaration; preserve its original input/schema.
    delete offer.extensions.bazaar.info.output;
    delete offer.extensions.bazaar.schema.properties.output;
    return { id: item.id, path: item.path, offer, handler: `object${i}`, admit: `admit${i}` };
  });
  return { schema: 'stellar-forge.seller-service.v1', publicOrigin: originText, routes };
}

/** Generate original seller config and native handler exports; does not start a seller. */
export async function configureS3Seller({ sourcePath, payment, origin, directory, source, resume = false }) {
  const description = source.describe();
  const service = compileS3Seller({ payment, origin, description });
  const out = resolve(directory);
  const sourceModule = new URL('./source.mjs', import.meta.url).href;
  const handlers = `// Generated for the ORIGINAL SF30 --handlers interface. Keep this file operator-private.\n` +
    `import { openS3ObjectFile } from ${JSON.stringify(sourceModule)};\n` +
    `const source = await openS3ObjectFile(${JSON.stringify(join(out, 'source.json'))});\n` +
    description.objects.map((item, i) => `const route${i} = source.route(${JSON.stringify(item.id)});\nexport const object${i} = route${i}.handler;\nexport const admit${i} = route${i}.admit;`).join('\n') +
    `\nexport const closeS3Source = source.close;\nexport const describeS3Source = source.describe;\n`;
  try { await mkdir(out, { mode: 0o700 }); }
  catch (error) {
    // Only a retained authoring operation requests replay. Original CLI setup
    // still requires a new directory; replay compares every published byte.
    if (!resume || error.code !== 'EEXIST' || !(await lstat(out)).isDirectory()) throw error;
  }
  await writeNew(join(out, 'source.json'), JSON.stringify(source.snapshotConfig(), null, 2) + '\n', resume);
  await writeNew(join(out, 'service.json'), JSON.stringify(service, null, 2) + '\n', resume);
  await writeNew(join(out, 'handlers.mjs'), handlers, resume);
  await writeNew(join(out, 'objects.json'), JSON.stringify(description, null, 2) + '\n', resume);
  return { schema: 'stellar-forge.s3-setup.v1', directory: out,
    source: join(out, 'source.json'), service: join(out, 'service.json'), handlers: join(out, 'handlers.mjs'), objects: description.objects.length,
    sellerCommand: [process.execPath, fileURLToPath(new URL('../serve.mjs', import.meta.url)),
      '--config', join(out, 'service.json'), '--handlers', join(out, 'handlers.mjs')],
    note: 'Start the original seller after inspection. Add its existing --facilitator option for native payments.' };
}

export async function main(args = process.argv.slice(2)) {
  if (args[0] === 'workspace') return (await import('./workspace/server.mjs')).main(args.slice(1));
  const parsed = argsOf(args);
  if (!parsed) { process.stdout.write(HELP + '\n'); return; }
  const { command, options } = parsed;
  const sourcePath = resolve(options.get('--source'));
  const source = await openS3ObjectFile(sourcePath);
  try {
    let result;
    if (command === 'describe') result = source.describe();
    if (command === 'inspect') {
      const query = Object.fromEntries(['offset', 'length'].filter(key => options.has(`--${key}`))
        .map(key => [key, options.get(`--${key}`)]));
      const route = source.route(options.get('--object'));
      const context = { method: 'GET', query, headers: {}, body: null };
      const admitted = route.admit(context);
      if (admitted !== true) throw new Error(admitted.body?.error ?? 'S3_INSPECTION_REJECTED');
      const output = resolve(options.get('--out'));
      // Reserve the destination before retrieving any object bytes.
      const file = await open(output, 'wx', 0o600); let complete = false;
      try {
        const response = await route.handler(context);
        if (![200, 206].includes(response.status)) throw new Error(response.body?.error ?? 'S3_INSPECTION_FAILED');
        await file.writeFile(response.body); await file.sync(); complete = true;
        result = { schema: 'stellar-forge.s3-inspection.v1', object: options.get('--object'),
          output, bytes: response.body.length, sha256: response.headers['x-content-sha256'],
          snapshot: response.headers['x-sf30-object-snapshot'],
          ...(response.headers['content-range'] ? { contentRange: response.headers['content-range'] } : {}) };
      } finally { await file.close(); if (!complete) await rm(output, { force: true }); }
    }
    if (command === 'configure') {
      const bytes = await readFile(resolve(options.get('--payment')));
      if (bytes.length > 65536) throw new TypeError('Payment file exceeds 64 KiB');
      const payment = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
      result = await configureS3Seller({ sourcePath, source, payment, origin: options.get('--origin'),
        directory: options.get('--directory') });
    }
    process.stdout.write(JSON.stringify(result, null, 2) + '\n');
    return result;
  } finally { source.close(); }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch(error => { process.stderr.write(String(error?.message ?? 'S3_OPERATOR_COMMAND_FAILED') + '\n'); process.exitCode = 1; });
}

// MIT. Operator configuration for private S3 objects served by the original SF30 runtime.
import { readFile, stat } from 'node:fs/promises';
import { resolve } from 'node:path';

const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const own = (value, key) => Object.prototype.hasOwnProperty.call(value, key);
const integer = (value, min, max, label) => {
  if (!Number.isSafeInteger(value) || value < min || value > max) throw new TypeError(`Invalid ${label}`);
  return value;
};
const text = (value, max, label) => {
  if (typeof value !== 'string' || !value || value.length > max || /[\x00-\x1f\x7f]/.test(value))
    throw new TypeError(`Invalid ${label}`);
  return value;
};
function keys(value, allowed, label) {
  if (!plain(value) || Object.keys(value).some(key => !allowed.includes(key)))
    throw new TypeError(`Invalid ${label} fields`);
}

/** Private configuration only: HTTP buyers never select a bucket, key or version. */
export function validateS3Config(raw) {
  keys(raw, ['schema', 'region', 'bucket', 'endpoint', 'forcePathStyle', 'allowLocalEndpoint',
    'credentialProvider', 'expectedBucketOwner', 'timeoutMs', 'maxInFlight', 'objects'], 'S3 source');
  if (raw.schema !== 'stellar-forge.s3-source.v1') throw new TypeError('Expected s3-source.v1');
  const region = text(raw.region, 64, 'region');
  if (!/^[a-z0-9][a-z0-9-]*$/.test(region)) throw new TypeError('Invalid region');
  const bucket = text(raw.bucket, 63, 'bucket');
  if (!/^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$/.test(bucket) || bucket.includes('..') ||
      /^\d+\.\d+\.\d+\.\d+$/.test(bucket) || bucket.endsWith('--x-s3'))
    throw new TypeError('Use an ordinary S3 bucket name');
  if (raw.forcePathStyle !== undefined && typeof raw.forcePathStyle !== 'boolean')
    throw new TypeError('forcePathStyle must be boolean');
  if (raw.allowLocalEndpoint !== undefined && typeof raw.allowLocalEndpoint !== 'boolean')
    throw new TypeError('allowLocalEndpoint must be boolean');
  let endpoint;
  if (raw.endpoint !== undefined) {
    const url = new URL(text(raw.endpoint, 2048, 'endpoint'));
    const local = raw.allowLocalEndpoint === true && url.protocol === 'http:' && url.hostname === '127.0.0.1';
    if ((!local && url.protocol !== 'https:') || url.username || url.password || url.search || url.hash ||
        url.pathname !== '/') throw new TypeError('Endpoint requires an HTTPS origin, or explicitly enabled loopback HTTP');
    endpoint = url.origin;
  } else if (raw.allowLocalEndpoint) throw new TypeError('Local mode requires an explicit endpoint');
  const credentialProvider = raw.credentialProvider ?? 'environment';
  if (!['environment', 'default'].includes(credentialProvider)) throw new TypeError('Invalid credentialProvider');
  if (raw.expectedBucketOwner !== undefined && !/^\d{12}$/.test(raw.expectedBucketOwner))
    throw new TypeError('expectedBucketOwner must be a 12-digit account ID');
  if (!Array.isArray(raw.objects) || raw.objects.length < 1 || raw.objects.length > 64)
    throw new TypeError('Configure 1–64 objects');
  const ids = new Set(), paths = new Set();
  const objects = raw.objects.map((item, index) => {
    keys(item, ['id', 'path', 'key', 'versionId', 'etag', 'expectedBytes', 'sha256', 'mode',
      'maxBytes', 'contentType', 'filename', 'description'], `object ${index}`);
    const id = text(item.id, 64, 'object ID');
    if (!/^[A-Za-z0-9_-]+$/.test(id) || ids.has(id)) throw new TypeError('Unique object ID required');
    const path = text(item.path, 256, 'route path');
    if (!/^\/[A-Za-z0-9_.~/-]+$/.test(path) || path.includes('//') || path.startsWith('/_seller/') ||
        new URL(path, 'https://seller.example').pathname !== path || paths.has(path))
      throw new TypeError('Unique canonical fixed route path required');
    const key = text(item.key, 1024, 'object key');
    if (Buffer.byteLength(key) > 1024) throw new TypeError('S3 object key exceeds 1024 UTF-8 bytes');
    const mode = item.mode ?? 'whole';
    if (!['whole', 'chunks'].includes(mode)) throw new TypeError('Invalid delivery mode');
    const maxBytes = integer(item.maxBytes ?? 921600, 1, 1048576, 'object response byte limit');
    const contentType = text(item.contentType ?? 'application/octet-stream', 128, 'content type');
    if (!/^[A-Za-z0-9!#$&^_.+-]+\/[A-Za-z0-9!#$&^_.+-]+(?:; charset=utf-8)?$/.test(contentType))
      throw new TypeError('Invalid content type');
    const filename = text(item.filename ?? `${id}.bin`, 120, 'download filename');
    if (!/^[A-Za-z0-9][A-Za-z0-9_. -]*$/.test(filename) || filename.endsWith('.') || filename.endsWith(' '))
      throw new TypeError('Download filename must be a portable basename');
    const object = { id, path, key, mode, maxBytes, contentType, filename,
      description: text(item.description ?? `Download ${id}`, 512, 'description') };
    if (own(item, 'versionId')) object.versionId = text(item.versionId, 1024, 'version ID');
    if (own(item, 'etag')) object.etag = text(item.etag, 1024, 'ETag');
    if (own(item, 'expectedBytes')) object.expectedBytes = integer(item.expectedBytes, 0, Number.MAX_SAFE_INTEGER, 'expected bytes');
    if (own(item, 'sha256')) {
      if (mode !== 'whole' || !/^[a-f0-9]{64}$/.test(item.sha256)) throw new TypeError('sha256 requires whole mode and lowercase hex');
      object.sha256 = item.sha256;
    }
    ids.add(id); paths.add(path);
    return Object.freeze(object);
  });
  return Object.freeze({ schema: raw.schema, region, bucket, ...(endpoint ? { endpoint } : {}),
    allowLocalEndpoint: raw.allowLocalEndpoint ?? false,
    forcePathStyle: raw.forcePathStyle ?? Boolean(endpoint), credentialProvider,
    ...(raw.expectedBucketOwner ? { expectedBucketOwner: raw.expectedBucketOwner } : {}),
    timeoutMs: integer(raw.timeoutMs ?? 10000, 100, 60000, 'source deadline'),
    maxInFlight: integer(raw.maxInFlight ?? 4, 1, 32, 'source capacity'), objects: Object.freeze(objects) });
}

export async function readS3Config(file) {
  const path = resolve(file), info = await stat(path);
  if (!info.isFile() || info.size > 1048576) throw new TypeError('Source must be a regular JSON file up to 1 MiB');
  const bytes = await readFile(path);
  if (bytes.length > 1048576) throw new TypeError('Source exceeds 1 MiB');
  return validateS3Config(JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)));
}

// MIT. Read-only S3 application adapter. Native SF30 alone controls payment and delivery.
import { createHash } from 'node:crypto';
import { readS3Config, validateS3Config } from './config.mjs';

const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const failure = (code, status = 503) => Object.assign(new Error(code), { code, status });
const response = error => ({ status: error.status ?? 503, body: { error: error.code ?? 'S3_SOURCE_UNAVAILABLE' } });
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const own = (value, key) => Object.prototype.hasOwnProperty.call(value, key);
const CONTROLS = ['range', 'if-match', 'if-none-match', 'if-range', 'if-modified-since', 'if-unmodified-since'];

function safeFailure(error, signal) {
  if (signal?.aborted) return signal.reason?.code ? signal.reason : failure('S3_REQUEST_ABORTED', 503);
  if (typeof error?.code === 'string' && error.code.startsWith('S3_')) return error;
  const status = error?.$metadata?.httpStatusCode;
  if (status === 404 || status === 412 || ['NoSuchKey', 'NoSuchVersion', 'PreconditionFailed'].includes(error?.name))
    return failure('S3_OBJECT_CHANGED_OR_UNAVAILABLE', 409);
  if (status === 416) return failure('S3_OBJECT_RANGE_UNAVAILABLE', 409);
  return failure('S3_SOURCE_UNAVAILABLE');
}

function shape(head, item) {
  if (!Number.isSafeInteger(head.ContentLength) || head.ContentLength < 0 ||
      typeof head.ETag !== 'string' || !head.ETag || head.ETag.length > 1024 || /[\x00-\x1f\x7f]/.test(head.ETag) ||
      head.DeleteMarker === true) throw failure('S3_OBJECT_METADATA_INVALID');
  if (head.ContentEncoding && head.ContentEncoding !== 'identity') throw failure('S3_OBJECT_CONTENT_ENCODING_UNSUPPORTED');
  if (item.expectedBytes !== undefined && item.expectedBytes !== head.ContentLength ||
      item.etag !== undefined && item.etag !== head.ETag ||
      item.versionId !== undefined && item.versionId !== head.VersionId)
    throw failure('S3_CONFIGURED_OBJECT_CHANGED', 409);
  if (item.mode === 'whole' && head.ContentLength > item.maxBytes) throw failure('S3_OBJECT_REQUIRES_CHUNKS', 413);
  let versionId;
  if (head.VersionId !== undefined) {
    if (typeof head.VersionId !== 'string' || !head.VersionId || head.VersionId.length > 1024 || /[\x00-\x1f\x7f]/.test(head.VersionId))
      throw failure('S3_OBJECT_METADATA_INVALID');
    versionId = head.VersionId;
  }
  return Object.freeze({ bytes: head.ContentLength, etag: head.ETag, versionId,
    snapshot: hash(JSON.stringify({ id: item.id, bytes: head.ContentLength, etag: head.ETag, versionId: versionId ?? null })) });
}

function objectDescription(item, pinned) {
  return { id: item.id, path: item.path, description: item.description, mode: item.mode,
    bytes: pinned.bytes, maxBytes: item.maxBytes, contentType: item.contentType,
    filename: item.filename, snapshot: pinned.snapshot,
    versioned: pinned.versionId !== undefined && pinned.versionId !== 'null',
    ...(item.sha256 ? { expectedSha256: item.sha256 } : {}) };
}

/** Reopen an already pinned configuration without loading an SDK or reading S3. */
export function describePinnedS3Config(input) {
  const config = validateS3Config(input);
  const objects = config.objects.map(item => {
    if (item.etag === undefined || item.expectedBytes === undefined)
      throw new TypeError('Retained S3 objects require their selected ETag and exact byte count.');
    const pinned = shape({ ETag: item.etag, ContentLength: item.expectedBytes,
      ...(item.versionId === undefined ? {} : { VersionId: item.versionId }) }, item);
    return objectDescription(item, pinned);
  });
  return { schema: 'stellar-forge.s3-description.v1', closed: false, inFlight: 0,
    maxInFlight: config.maxInFlight, objects };
}

function selection(context, item, pinned) {
  if (!object(context) || context.method !== 'GET' || context.body !== null && context.body !== undefined)
    throw failure('S3_GET_REQUIRED', 405);
  if (object(context.headers) && Object.keys(context.headers).some(key => CONTROLS.includes(key.toLowerCase())))
    throw failure('S3_USE_OFFSET_LENGTH_QUERY', 400);
  if (context.pathParams && Object.keys(context.pathParams).length) throw failure('S3_FIXED_ROUTE_REQUIRED', 400);
  const query = context.query ?? {};
  if (!object(query)) throw failure('S3_INVALID_QUERY', 400);
  const allowed = item.mode === 'chunks' ? ['offset', 'length'] : [];
  if (Object.keys(query).some(key => !allowed.includes(key))) throw failure('S3_INVALID_QUERY', 400);
  const number = (name, fallback, min) => {
    if (!own(query, name)) return fallback;
    const value = query[name];
    if (typeof value !== 'string' || !/^(0|[1-9][0-9]*)$/.test(value) ||
        !Number.isSafeInteger(Number(value)) || Number(value) < min) throw failure('S3_INVALID_QUERY', 400);
    return Number(value);
  };
  if (item.mode === 'whole') return { offset: 0, bytes: pinned.bytes, range: null };
  const offset = number('offset', 0, 0), length = number('length', item.maxBytes, 1);
  if (length > item.maxBytes) throw failure('S3_CHUNK_TOO_LARGE', 413);
  if (offset >= pinned.bytes) throw failure('S3_OFFSET_OUTSIDE_OBJECT', 416);
  const bytes = Math.min(length, pinned.bytes - offset), end = offset + bytes - 1;
  return { offset, bytes, range: `bytes=${offset}-${end}`, contentRange: `bytes ${offset}-${end}/${pinned.bytes}` };
}

async function collect(body, wanted, signal) {
  if (!body || typeof body[Symbol.asyncIterator] !== 'function') throw failure('S3_OBJECT_BODY_UNAVAILABLE');
  const chunks = []; let count = 0;
  const abort = () => { if (typeof body.destroy === 'function') body.destroy(signal.reason); };
  signal.addEventListener('abort', abort, { once: true });
  try {
    signal.throwIfAborted();
    for await (const chunk of body) {
      signal.throwIfAborted();
      const bytes = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      count += bytes.length;
      if (count > wanted) throw failure('S3_RESPONSE_LENGTH_MISMATCH', 502);
      chunks.push(bytes);
    }
    if (count !== wanted) throw failure('S3_RESPONSE_LENGTH_MISMATCH', 502);
    return Buffer.concat(chunks, count);
  } finally {
    signal.removeEventListener('abort', abort);
    if (typeof body.destroy === 'function') body.destroy();
  }
}

/** Open and pin each approved object once. Pass an existing official SDK client when embedding. */
export async function createS3ObjectSource(input, { client: suppliedClient, sdk: suppliedSdk, env = process.env } = {}) {
  const config = validateS3Config(input);
  const sdk = suppliedSdk ?? await import('@aws-sdk/client-s3');
  if (typeof sdk.HeadObjectCommand !== 'function' || typeof sdk.GetObjectCommand !== 'function')
    throw new TypeError('Official S3 command classes required');
