  const active = new Set(), bindings = new Map(); let closed = false;
  const base = item => ({ Bucket: config.bucket, Key: item.key,
    ...(config.expectedBucketOwner ? { ExpectedBucketOwner: config.expectedBucketOwner } : {}) });
